def is_single(s):
    return "- Single" in s.get("collectionName", "")

def is_live(s):
    name = s.get("collectionName", "").upper()
    return "LIVE" in name or "TOUR" in name

# シングルでもライブでもない盤(アルバムなど)に入っている曲名
album_names = {s["trackName"] for s in songs if not is_single(s) and not is_live(s)}

#シングル盤の曲のうち、同じ曲名がアルバム側にもあるものを除く
cleaned = [s for s in songs if not (is_single(s) and s["trackName"] in album_names)]

print("除く前:", len(songs), "→ 除いた後:", len(cleaned))

import json
import math
import uuid
from urllib.request import Request, urlopen
from datetime import datetime, timezone, timedelta
from IPython.display import display, HTML

# ==========================================
# 1. ポケモン全18タイプ
# ==========================================

types = {
    "normal": ("ノーマル", "#A8A77A"),
    "fire": ("ほのお", "#EE8130"),
    "water": ("みず", "#6390F0"),
    "electric": ("でんき", "#F7D02C"),
    "grass": ("くさ", "#7AC74C"),
    "ice": ("こおり", "#96D9D6"),
    "fighting": ("かくとう", "#C22E28"),
    "poison": ("どく", "#A33EA1"),
    "ground": ("じめん", "#E2BF65"),
    "flying": ("ひこう", "#A98FF3"),
    "psychic": ("エスパー", "#F95587"),
    "bug": ("むし", "#A6B91A"),
    "rock": ("いわ", "#B6A136"),
    "ghost": ("ゴースト", "#735797"),
    "dragon": ("ドラゴン", "#6F35FC"),
    "dark": ("あく", "#705746"),
    "steel": ("はがね", "#B7B7CE"),
    "fairy": ("フェアリー", "#D685AD")
}

# ==========================================
# 2. PokéAPIからデータを取得
# ==========================================

def get_json(url):
    request = Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0",
            "Accept": "application/json"
        }
    )

    with urlopen(request, timeout=30) as response:
        return json.load(response)


chart = {}

print("PokéAPIからタイプ相性を取得しています...")

for attack in types:

    url = f"https://pokeapi.co/api/v2/type/{attack}/"
    data = get_json(url)

    relations = data["damage_relations"]

    chart[attack] = {
        defense: 1.0 for defense in types
    }

    for item in relations["double_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 2.0

    for item in relations["half_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 0.5

    for item in relations["no_damage_to"]:
        name = item["name"]
        if name in types:
            chart[attack][name] = 0.0

print("全18タイプのデータ取得が完了しました。")


# ==========================================
# 3. 円形グラフの位置を計算
# ==========================================

size = 1000
cx = cy = size / 2

radius = 395
node_radius = 36

names = list(types.keys())
positions = {}

for i, name in enumerate(names):

    angle = (
        -math.pi / 2
        + 2 * math.pi * i / len(names)
    )

    x = cx + radius * math.cos(angle)
    y = cy + radius * math.sin(angle)

    positions[name] = (x, y)


# ==========================================
# 4. SVGの作成
# ==========================================

uid = "pokemon_" + uuid.uuid4().hex[:10]

svg = f"""
<div id="{uid}" style="
    max-width:1050px;
    margin:auto;
    font-family:'Yu Gothic',sans-serif;
">

<h2 style="text-align:center;">
ポケモン全18タイプ相性図
</h2>

<p style="text-align:center;">
<span style="color:#e53935;">● 効果抜群（2倍）</span>　
<span style="color:#1565c0;">● いまひとつ（0.5倍）</span>　
<span style="color:#333;">● 効果なし（0倍）</span>
</p>

<svg viewBox="0 0 1000 1000"
     style="width:100%;background:#fafafa;border-radius:18px;">

<defs>

<marker id="{uid}_red"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#e53935"/>
</marker>

<marker id="{uid}_blue"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#1565c0"/>
</marker>

<marker id="{uid}_black"
markerWidth="7" markerHeight="7"
refX="6" refY="3" orient="auto">
<path d="M0 0 L6 3 L0 6 Z" fill="#333"/>
</marker>

</defs>

<g class="edges">
"""


# ==========================================
# 5. タイプ相性の矢印を描画
# ==========================================

for attack in names:

    for defense in names:

        value = chart[attack][defense]

        # 等倍は矢印を描かない
        if value == 1:
            continue

        x1, y1 = positions[attack]
        x2, y2 = positions[defense]

        dx = x2 - x1
        dy = y2 - y1

        distance = math.hypot(dx, dy)

        if distance == 0:
            continue

        ux = dx / distance
        uy = dy / distance

        start_x = x1 + ux * (node_radius + 5)
        start_y = y1 + uy * (node_radius + 5)

        end_x = x2 - ux * (node_radius + 10)
        end_y = y2 - uy * (node_radius + 10)

        if value == 2:
            color = "#e53935"
            marker = "red"
            width = 3

        elif value == 0.5:
            color = "#1565c0"
            marker = "blue"
            width = 2

        else:
            color = "#333333"
            marker = "black"
            width = 2

        svg += f"""
        <line
            class="edge"
            data-attack="{attack}"
            data-defense="{defense}"
            data-value="{value}"
            x1="{start_x:.2f}"
            y1="{start_y:.2f}"
            x2="{end_x:.2f}"
            y2="{end_y:.2f}"
            stroke="{color}"
            stroke-width="{width}"
            stroke-opacity="0.25"
            marker-end="url(#{uid}_{marker})"
        />
        """


svg += '</g><g class="nodes">'


# ==========================================
# 6. タイプの丸を描画
# ==========================================

for name in names:

    label, color = types[name]
    x, y = positions[name]

    svg += f"""
    <g class="type-node"
       data-type="{name}"
       style="cursor:pointer;">

        <circle
            cx="{x:.2f}"
            cy="{y:.2f}"
            r="{node_radius}"
            fill="{color}"
            stroke="#333333"
            stroke-width="2"
        />

        <text
            x="{x:.2f}"
            y="{y + 5:.2f}"
            text-anchor="middle"
            font-size="13"
            font-weight="bold"
            fill="white"
            style="pointer-events:none;"
        >{label}</text>

    </g>
    """


svg += """
</g>

<text x="500" y="485"
text-anchor="middle"
font-size="28"
font-weight="bold"
fill="#333">
ポケモン
</text>

<text x="500" y="525"
text-anchor="middle"
font-size="20"
fill="#555">
全18タイプ相性
</text>

<text x="500" y="555"
text-anchor="middle"
font-size="14"
fill="#777">
タイプをクリックして確認
</text>

</svg>

<div class="type-info"
style="
    text-align:center;
    padding:15px;
    font-size:18px;
    font-weight:bold;
">
全18タイプの相性を表示中
</div>

<div class="type-detail"
style="
    text-align:center;
    padding:10px;
    font-size:15px;
    line-height:1.8;
">
タイプを選ぶと、攻撃相性が表示されます。
</div>

</div>
"""


# ==========================================
# 7. クリック操作を追加
# ==========================================

script = """
<script>
(function(){

    const root = document.getElementById("__UID__");

    if (!root) return;

    const nodes = root.querySelectorAll(".type-node");
    const edges = root.querySelectorAll(".edge");
    const graph = root.querySelector("svg");

    const info = root.querySelector(".type-info");
    const detail = root.querySelector(".type-detail");

    const labels = __LABELS__;
    const chart = __CHART__;

    let selected = null;

    function update(type){

        selected = type;

        // タイプの表示
        nodes.forEach(node => {

            const name = node.dataset.type;

            const active = (
                !type ||
                name === type ||
                (type && chart[type][name] !== 1)
            );

            node.style.opacity = active ? "1" : "0.2";

            const circle = node.querySelector("circle");

            circle.setAttribute(
                "stroke-width",
                type && name === type ? "6" : "2"
            );

            circle.setAttribute(
                "stroke",
                type && name === type ? "#111" : "#333"
            );
        });

        // 矢印の表示
        edges.forEach(edge => {

            const active = (
                !type ||
                edge.dataset.attack === type
            );

            edge.style.opacity = active ? "1" : "0.015";

            edge.setAttribute(
                "stroke-opacity",
                type && active ? "1" : "0.25"
            );

        });

        if (!type){

            info.textContent =
                "全18タイプの相性を表示中";

            detail.textContent =
                "タイプを選ぶと、攻撃相性が表示されます。";

            return;
        }

        info.textContent =
            labels[type] + "タイプで攻撃した場合";

        const strong = [];
        const weak = [];
        const zero = [];

        Object.keys(chart[type]).forEach(defense => {

            const value = chart[type][defense];

            if(value === 2){
                strong.push(labels[defense]);
            }
            else if(value === 0.5){
                weak.push(labels[defense]);
            }
            else if(value === 0){
                zero.push(labels[defense]);
            }

        });

        detail.innerHTML =
            '<span style="color:#e53935;">' +
            '効果抜群：' +
            (strong.join("、") || "なし") +
            '</span><br>' +

            '<span style="color:#1565c0;">' +
            'いまひとつ：' +
            (weak.join("、") || "なし") +
            '</span><br>' +

            '<span style="color:#333;">' +
            '効果なし：' +
            (zero.join("、") || "なし") +
            '</span>';

    }

    // タイプをクリック
    nodes.forEach(node => {

        node.addEventListener("click", function(event){

            event.stopPropagation();

            const type = node.dataset.type;

            if(selected === type){
                update(null);
            }
            else{
                update(type);
            }

        });

    });

    // タイプ以外をクリックすると元に戻す
    graph.addEventListener("click", function(event){

        if(!event.target.closest(".type-node")){
            update(null);
        }

    });

})();
</script>
"""

script = script.replace("__UID__", uid)

script = script.replace(
    "__LABELS__",
    json.dumps(
        {k: v[0] for k, v in types.items()},
        ensure_ascii=False
    )
)

script = script.replace(
    "__CHART__",
    json.dumps(chart)
)

display(HTML(svg + script))


# ==========================================
# 8. 効果抜群ランキング
# ==========================================

print("\n【効果抜群にできるタイプ数ランキング】")

ranking = []

for attack in names:

    count = sum(
        value == 2
        for value in chart[attack].values()
    )

    ranking.append(
        (types[attack][0], count)
    )

ranking.sort(
    key=lambda item: item[1],
    reverse=True
)

for i, (name, count) in enumerate(ranking, 1):
    print(f"{i}位：{name}（{count}タイプ）")


# ==========================================
# 9. 出典と取得日
# ==========================================

jst = timezone(timedelta(hours=9))

today = datetime.now(jst).strftime(
    "%Y年%m月%d日"
)

print("\n取得日：", today)

print("出典：https://pokeapi.co/docs/v2#types")
print("API：https://pokeapi.co/api/v2/type/")

