MASK = ""  # 陸地を2度ごとの点で表した地図データ（Natural Earth 110mの陸地から作成）

TEMPLATE = r'''
(function(){
const ID="__ID__",DATA=__DATA__,MASK="__MASK__";
const root=document.getElementById(ID);
const cv=root.querySelector('canvas'),cx=cv.getContext('2d');
const msg=root.querySelector('.msg'),card=root.querySelector('.card');
const W=180,H=90,rad=Math.PI/180;
const bin=atob(MASK),land=[];
for(let j=0;j<H;j++)for(let i=0;i<W;i++){const k=j*W+i;if(bin.charCodeAt(k>>3)>>(k&7)&1)land.push([90-(j+.5)*2,-180+(i+.5)*2]);}
const unit=(la,lo)=>[Math.cos(la*rad)*Math.sin(lo*rad),Math.sin(la*rad),Math.cos(la*rad)*Math.cos(lo*rad)];
const pts=land.map(([la,lo])=>unit(la,lo));
const w=cv.width,h=cv.height,R=Math.min(w,h)*.40,X0=w/2,Y0=h/2;
let rotLon=140,rotLat=20,target=null,auto=true,hl=null,amt=0;
function proj(la,lo){const a=la*rad,b=(lo-rotLon)*rad,c=rotLat*rad;
  const x=Math.cos(a)*Math.sin(b),y=Math.sin(a),z=Math.cos(a)*Math.cos(b);
  return [x,y*Math.cos(c)-z*Math.sin(c),y*Math.sin(c)+z*Math.cos(c)];}
function draw(t){
  amt+=((hl?1:0)-amt)*.05;
  const pulse=(Math.sin(t/450)+1)/2,eb=hl&&hl.globe?amt:0;
  cx.clearRect(0,0,w,h);
  const g=cx.createRadialGradient(X0,Y0,R*.9,X0,Y0,R*(1.35+eb*.25));
  g.addColorStop(0,'rgba('+(79+eb*150|0)+','+(209+eb*30|0)+',255,'+(.16+eb*.35)+')');g.addColorStop(1,'rgba(79,209,255,0)');
  cx.fillStyle=g;cx.beginPath();cx.arc(X0,Y0,R*1.6,0,7);cx.fill();
  cx.fillStyle='#07101e';cx.beginPath();cx.arc(X0,Y0,R,0,7);cx.fill();
  for(let i=0;i<land.length;i++){
    const[p,q,z]=proj(land[i][0],land[i][1]);if(z<=0)continue;
    let a=.25+z*.6,s=2,r=120,gr=200,b=255;
    if(hl){let k;
      if(hl.globe)k=.55+.45*pulse;
      else{const d=pts[i][0]*hl.u[0]+pts[i][1]*hl.u[1]+pts[i][2]*hl.u[2];k=Math.exp(-Math.pow(Math.acos(Math.max(-1,Math.min(1,d)))/.22,2));}
      a=a*(1-.55*amt*(1-k))+k*amt*.6;s=2+k*amt*2.2;r=120+k*amt*135;gr=200+k*amt*55;b=255-k*amt*120;}
    cx.fillStyle='rgba('+(r|0)+','+(gr|0)+','+(b|0)+','+Math.min(1,a)+')';
    cx.fillRect(X0+p*R-s/2,Y0-q*R-s/2,s,s);
  }
  cx.strokeStyle='rgba('+(79+eb*150|0)+',209,255,'+(.35+eb*.5)+')';cx.lineWidth=1.2+eb*1.5;cx.beginPath();cx.arc(X0,Y0,R,0,7);cx.stroke();
  if(hl&&!hl.globe){const[p,q,z]=proj(hl.lat,hl.lon);
    if(z>0){const X=X0+p*R,Y=Y0-q*R,gr=R*.32*amt;
      const g2=cx.createRadialGradient(X,Y,0,X,Y,gr);
      g2.addColorStop(0,'rgba(255,235,170,'+(.75*amt)+')');g2.addColorStop(.4,'rgba(255,190,90,'+(.25*amt)+')');g2.addColorStop(1,'rgba(255,170,60,0)');
      cx.fillStyle=g2;cx.beginPath();cx.arc(X,Y,gr,0,7);cx.fill();
      cx.fillStyle='#fff';cx.beginPath();cx.arc(X,Y,4.5,0,7);cx.fill();
      for(let n=0;n<2;n++){const ph=((t/1400)+n*.5)%1;cx.strokeStyle='rgba(255,220,140,'+((1-ph)*.8*amt)+')';cx.lineWidth=1.5;cx.beginPath();cx.arc(X,Y,6+ph*34,0,7);cx.stroke();}}}
  if(target){let d=target.lon-rotLon;d=((d+540)%360)-180;rotLon+=d*.06;rotLat+=(target.lat-rotLat)*.06;
    if(Math.abs(d)<.05&&Math.abs(target.lat-rotLat)<.05)target=null;}
  else if(auto)rotLon+=.06;
  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
let drag=null;
cv.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];auto=false;target=null;cv.setPointerCapture(e.pointerId)});
cv.addEventListener('pointermove',e=>{if(!drag)return;rotLon-=(e.clientX-drag[0])*.3;rotLat=Math.max(-85,Math.min(85,rotLat+(e.clientY-drag[1])*.3));drag=[e.clientX,e.clientY]});
cv.addEventListener('pointerup',()=>{drag=null});
function show(key){
  const d=DATA[key];if(!d)return;
  root.querySelectorAll('button').forEach(b=>b.style.background=b.textContent===key?'#4fd1ff':'#0d1a2e');
  root.querySelectorAll('button').forEach(b=>b.style.color=b.textContent===key?'#05080f':'#dce8ff');
  if(d.lat==null){hl={globe:true};target=null;auto=true;}
  else{hl={lat:d.lat,lon:d.lon,u:unit(d.lat,d.lon)};amt=0;target={lat:d.lat,lon:d.lon};auto=false;}
  card.style.display='block';
  card.querySelector('.t').textContent=d.title;
  card.querySelector('.d').textContent=d.description||'';
  card.querySelector('.w').textContent='場所: '+d.how;
  card.querySelector('.x').textContent=d.extract||'';
  card.querySelector('a').href=d.url;
  msg.textContent=d.lat==null?'地球全体を光らせています。':d.title+' の場所へ回転しました。';
}
root.querySelectorAll('button').forEach(b=>b.onclick=()=>show(b.textContent));
})();
'''

